with scored as (select id, store_id, product_id, quantity, last_restock, count(quantity) over (partition by product_id) as product_id_count_quantity, row_number() over (partition by store_id order by last_restock desc, id asc) as row_seq, avg(quantity) over (partition by store_id order by quantity asc, id asc rows between 2 preceding and 1 preceding) as quantity_avg_2_prior, sum(quantity) over (partition by product_id order by quantity asc, id asc rows between unbounded preceding and current row) as cumulative_quantity from inventory) select date_trunc('quarter', last_restock) as quarter_start, date_trunc('week', last_restock) as week_start, percentile_approx(cumulative_quantity, array(0.25, 0.5, 0.75)) as cumulative_quantity_quartiles, percentile_approx(product_id_count_quantity, 0.5) as product_id_count_quantity_p50, round(avg(quantity_avg_2_prior), 2) as avg_quantity_avg_2_prior from scored group by cube (date_trunc('quarter', last_restock), date_trunc('week', last_restock)) having product_id_count_quantity_p50 > 0
